{
  "labels": [
    {
      "i": 0,
      "speaker": "bot",
      "text": "Hello पवन गोयल जी आपको lifting machine की requirement है ना?"
    },
    {
      "i": 1,
      "speaker": "caller",
      "text": "Hello."
    },
    {
      "i": 2,
      "speaker": "caller",
      "text": "हाँ Madam."
    },
    {
      "i": 3,
      "speaker": "bot",
      "text": "ठीक है?"
    },
    {
      "i": 4,
      "speaker": "bot",
      "text": "मैं Tanya बोल रही हूं IndiaMART से।"
    },
    {
      "i": 5,
      "speaker": "bot",
      "text": "हमारे पास कई अच्छे sellers available हैं जिनसे मैं अभी आपको connect करवाऊंगी।"
    },
    {
      "i": 6,
      "speaker": "bot",
      "text": "बस कुछ details confirm कर दीजिए।"
    },
    {
      "i": 7,
      "speaker": "bot",
      "text": "बताइए lifting capacity में क्या prefer करेंगे एक ton या 500 kilograms या कोई और?"
    },
    {
      "i": 8,
      "speaker": "caller",
      "text": "कई।"
    },
    {
      "i": 9,
      "speaker": "bot",
      "text": "Total"
    },
    {
      "i": 10,
      "speaker": "bot",
      "text": "समझ गई।"
    },
    {
      "i": 11,
      "speaker": "bot",
      "text": "अब travel height के बारे में बात कर लेते हैं।"
    },
    {
      "i": 12,
      "speaker": "bot",
      "text": "आपको कौन सा चाहिए जैसे 10 feet, 12 feet या कुछ और?"
    },
    {
      "i": 13,
      "speaker": "caller",
      "text": "मैडम ये आप लोगों को चाहिए 20 feet।"
    },
    {
      "i": 14,
      "speaker": "bot",
      "text": "ठीक है।"
    },
    {
      "i": 15,
      "speaker": "bot",
      "text": "ये आपको"
    },
    {
      "i": 16,
      "speaker": "bot",
      "text": "तो मैं seller details WhatsApp पे भेज दूंगी जिनसे आप details और price discuss कर सकते हैं।"
    },
    {
      "i": 17,
      "speaker": "caller",
      "text": "ठीक है मैडम।"
    },
    {
      "i": 18,
      "speaker": "caller",
      "text": "IndiaMART चुनने के लिए धन्यवाद।"
    },
    {
      "i": 19,
      "speaker": "caller",
      "text": "आपका दिन शुभ हो।"
    },
    {
      "i": 20,
      "speaker": "bot",
      "text": "पूछना है।"
    }
  ]
}
